        "descriptif": "L’Institut Agro-Dijon est une Grande école formant des Ingénieurs dans les domaines de l’agronomie et de l’alimentation. La formation Ingénieur en alimentation permet d’étudier la nutrition, la microbiologie, le génie des procédés alimentaires … La formation Ingénieur agronome inclus l’étude des élevages, des productions végétales, de l’agroéquipement, … Les deux formations proposent plusieurs spécialisations parmi lesquelles biotechnologies microbiennes et fermentations alimentaires, connaissances et commerce des vins, gestion et protection des sols…",
