        "banque_tb": "Polytech",
        "descriptif": "POLYTECH Grenoble est une école d’ingénieur propose plusieurs spécialités. La spécialité Gestion des risques QHSE (Qualité Hygiène Sécurité Environnement) traite des questions de sécurité associées aux risques industriels et environnementaux mais aussi celles concernant la santé de l’Homme au travail. La spécialité Technologies de l'information pour la santé forme à l’analyse des besoins et la conception des systèmes d’information, des logiciels et des dispositifs dédiés à la santé. Cette spécialité est en partenariat avec le CHU de Grenoble Alpes, des laboratoires de recherche du bassin… La spécialité Géotechnique et Génie civil, proposée aux étudiants de BCPST/TB, permet d’étudier risques géologiques et géotechniques, la conception d’ouvrages, la gestion de projets d’ouvrage, … L’école propose plusieurs doubles diplômes, des échanges et des stages à l’étranger.",
