        "banque_tb": "Agro-Véto",
        "descriptif": "Le campus d’Angers de l’Institut Agro Rennes-Angers forme des ingénieurs en horticulture et des ingénieurs en paysage. Les domaines d’activité de l’ingénieur en horticulture sont divers, depuis la création de matériel végétal jusqu’au pilotage de structures ou entreprises impliquées dans les filières de l'horticulture, en passant par le contrôle de la qualité des produits dans les filières du végétal. L’ingénieur en paysage est plutôt spécialisé dans la conception et la réalisation de projets en paysage.",
        "lien_site": "https://institut-agro-rennes-angers.fr",
